    // ---------- 返工代次生成与重新放行 ----------

    @Test
    void rework_rejectedBatch_createsNextGeneration_sourceBecomesReworked_andRerunsFullFlow()
            throws Exception {
        String source = "BK-RW-S-" + unique();
        createBatch(source, List.of("外观", "含量"), 201);
        submitTest(source, "外观", "PASS", "insp-1", 201);
