        MvcResult replayByReworkKey = mockMvc.perform(post("/api/batches/" + source + "/rework")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reworkBody("CK-OTHER", reworkKey, rwBatch, "LOT-RW", "返工说明")))
