        String occupied = "BK-ROLL-EXIST-" + unique();
        createBatch(occupied, List.of("t1"), 201);

        // 返工批次键已存在 → 整次 409 回滚：原批次仍 REJECTED，无血缘边/返工登记/新批次
        rework(source, "CK-ROLL", "RK-ROLL-" + unique(), occupied, "LOT", "说明", 409);
