    // ---------- 返工前置状态 ----------

    @Test
    void rework_wrongStatus_returns409() throws Exception {
        // QUARANTINED：尚未完成检验
        String quarantined = "BK-WS-Q-" + unique();
        createBatch(quarantined, List.of("t1"), 201);
        rework(quarantined, "CK-WS-Q", "RK-WS-Q-" + unique(), "BK-WS-QN-" + unique(), "L", "r", 409);

